// src/pwa/registerPwa.js
// ─────────────────────────────────────────────────────────────────────────────
// Registers the service worker generated by vite-plugin-pwa (vite.config.js).
// The worker caches the app SHELL only (HTML, JS, CSS, fonts, icons) so the
// app opens with no internet. It never caches API responses; saved data is
// handled inside the app, per logged-in user.
//
// registerType "prompt": a new deploy is downloaded in the background but NOT
// switched to until staff tap "Reload" (UpdatePrompt.jsx). An auto-reload in
// the middle of taking an order or on the kitchen board would lose work.
// ─────────────────────────────────────────────────────────────────────────────
import { registerSW } from "virtual:pwa-register";

export const PWA_NEED_REFRESH = "pwa:need-refresh";

const UPDATE_CHECK_MS = 60 * 60 * 1000; // tablets stay open all shift — look for a new deploy hourly

let applyUpdate = null;
let needRefresh = false;

/** True once a new version is waiting (for a prompt mounted after the event fired). */
export const isUpdateWaiting = () => needRefresh;

/** Switches to the waiting version and reloads the page. */
export const reloadToUpdate = () => (applyUpdate ? applyUpdate(true) : window.location.reload());

/** Call once from main.jsx. Safe where service workers are unsupported (no-op). */
export const registerPwa = () => {
  if (applyUpdate || !("serviceWorker" in navigator)) return;
  applyUpdate = registerSW({
    onNeedRefresh() {
      needRefresh = true;
      window.dispatchEvent(new Event(PWA_NEED_REFRESH));
    },
    onRegisteredSW(_swUrl, registration) {
      if (!registration) return;
      // Seed the offline copy of /config.js (backend address). It is
      // network-first, not precached, so a server-side edit takes effect on
      // the next online load; this fetch makes sure a copy exists for the
      // first offline start.
      const warm = () => fetch("/config.js", { cache: "no-store" }).catch(() => {});
      if (navigator.serviceWorker.controller) warm();
      else navigator.serviceWorker.addEventListener("controllerchange", warm, { once: true });

      setInterval(() => {
        if (navigator.onLine && !registration.installing) registration.update().catch(() => {});
      }, UPDATE_CHECK_MS);
    },
  });
};
